      cursor: pointer;
    }
  </style>
</head>
<body>
  <header>
    <nav>
      <div class="logo" aria-label="Pobrecita home">
        <span>🐾</span> Pobrecita
      </div>
      <button class="menu-toggle" aria-label="Toggle menu">☰</button>
      <ul class="nav-links">
        <li><a href="#about">About</a></li>
        <li><a href="#gallery">Gallery</a></li>
        <li><a href="#personality">Personality</a></li>
        <li><a href="#contact">Contact</a></li>
      </ul>
    </nav>
  </header>

  <section class="hero" id="home">
    <div class="hero-text">
      <h1>Pobrecita the Dog</h1>
      <p>
        A small dog with a giant heart. Pobrecita means “poor little thing” — but she is rich in love, zoomies, and tail wags.
      </p>
      <a href="#contact" class="cta-button">Send Pobrecita a Treat</a>
    </div>
    <div class="hero-image">
      <img src="https://placehold.co/600x500/ffecd2/3b2f2f?text=Pobrecita+🐕" alt="Pobrecita the dog sitting happily" />
    </div>
  </section>

  <section id="about">
    <h2>About Pobrecita</h2>
    <div class="about-card">
      <img src="https://placehold.co/500x400/ffffff/3b2f2f?text=Sweet+Pobrecita" alt="Close-up of Pobrecita" />
      <div>
        <p>
          Pobrecita is a scrappy little companion who turned a ruff start into a life full of cuddles and sunshine. She was found wandering the neighborhood with nothing but a wagging tail and a heart full of hope.
        </p>
        <p>
          Today she spends her days napping in sunbeams, chasing squirrels, and reminding everyone that the best things come in small, scruffy packages.
        </p>
        <div class="facts">
          <div class="fact"><strong>Breed</strong>Mystery mix</div>
          <div class="fact"><strong>Age</strong>3 years</div>
          <div class="fact"><strong>Weight</strong>18 lbs</div>
          <div class="fact"><strong>Superpower</strong>Endless love</div>
        </div>
      </div>
    </div>
  </section>

  <section id="gallery">
