    <div class="gallery">
      <img src="https://placehold.co/400x300/ffe0b2/3b2f2f?text=Naptime" alt="Pobrecita napping" />
      <img src="https://placehold.co/400x300/cffafe/3b2f2f?text=Park+Adventures" alt="Pobrecita at the park" />
      <img src="https://placehold.co/400x300/e2f0cb/3b2f2f?text=Treat+Time" alt="Pobrecita enjoying a treat" />
      <img src="https://placehold.co/400x300/f6e1f6/3b2f2f?text=Cozy+Pup" alt="Pobrecita cozy in a blanket" />
